import time
from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock=None):
        if capacity <= 0:
            raise ValueError("Capacity must be greater than 0")
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock or time.monotonic
        self.cache = OrderedDict()  # Stores key -> (value, expiry_time)

    def _is_expired(self, expiry_time: float, now: float) -> bool:
        return now > expiry_time

    def get(self, key):
        if key not in self.cache:
            return None

        val, expiry = self.cache[key]
        now = self.clock()

        if self._is_expired(expiry, now):
            del self.cache[key]
            return None

        # Mark as recently used
        self.cache.move_to_end(key)
        return val

    def put(self, key, value):
        now = self.clock()
        expiry = now + self.ttl

        if key in self.cache:
            del self.cache[key]

        self.cache[key] = (value, expiry)

        # Evict the least recently used if over capacity
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

    def __len__(self):
        # Clean up expired items and return the count of active items
        now = self.clock()
        expired_keys = [
            k for k, (_, expiry) in self.cache.items() 
            if self._is_expired(expiry, now)
        ]
        for k in expired_keys:
            del self.cache[k]
        return len(self.cache)
