class Emitter {
  constructor() {
    // Map<event, Array<{ fn, wrapper }>>
    // `fn` is the original handler (used for off matching),
    // `wrapper` is what actually gets invoked (differs for once).
    this._events = new Map();
  }

  on(event, fn) {
    if (typeof fn !== 'function') {
      throw new TypeError('listener must be a function');
    }
    const list = this._events.get(event) || [];
    list.push({ fn, wrapper: fn });
    this._events.set(event, list);
    return this;
  }

  once(event, fn) {
    if (typeof fn !== 'function') {
      throw new TypeError('listener must be a function');
    }
    const self = this;
    const wrapper = function (...args) {
      // Remove before running so a re-entrant emit cannot fire it twice.
      self.off(event, fn);
      return fn.apply(this, args);
    };
    const list = this._events.get(event) || [];
    list.push({ fn, wrapper });
    this._events.set(event, list);
    return this;
  }

  off(event, fn) {
    const list = this._events.get(event);
    if (!list) return this;

    if (fn === undefined) {
      this._events.delete(event);
      return this;
    }

    // Remove the first matching handler by original fn.
    const idx = list.findIndex((entry) => entry.fn === fn);
    if (idx !== -1) {
      list.splice(idx, 1);
    }
    if (list.length === 0) {
      this._events.delete(event);
    }
    return this;
  }

  emit(event, ...args) {
    const list = this._events.get(event);
    if (!list || list.length === 0) return 0;

    // Iterate over a snapshot so mutations during emit are safe.
    const snapshot = list.slice();
    for (const entry of snapshot) {
      entry.wrapper.apply(this, args);
    }
    return snapshot.length;
